def _round(n, mode):
    return (n + 5000) // 10000 if mode == "half_up" else n // 10000


def _ledger(data, sequence_first, discounted, refunds):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = ((seq, event.get("revision", 0), pos) if sequence_first
               else (event.get("revision", 0), pos))
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if discounted else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        total = net + tax
        if refunds and event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_06(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    rows = {name: {r["version"]: r for r in versions}
            for name, versions in packages.items()}
    domains = [[-1] + sorted(rows[name]) for name in names]
    roots = data["roots"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_key = None
    best = None

    for vector in product(*domains):
        chosen = dict(zip(names, vector))
        if any(chosen.get(name, -1) < 0 or
               not bounds[0] <= chosen[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(version >= 0 and
               (version in blocked.get(name, []) or
                (name in pins and pins[name] != version))
               for name, version in chosen.items()):
            continue

        edges = {}
        valid = True
        for name, version in chosen.items():
            if version < 0:
                continue
            edges[name] = []
            row = rows[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                ov = chosen.get(other, -1)
                if ov < 0 or not dep["min"] <= ov <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        # The installed set must be precisely the active dependency closure.
        closure = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in closure:
                continue
            if chosen.get(name, -1) < 0 or name not in edges:
                valid = False
                break
            closure.add(name)
            stack.extend(edges[name])
        if not valid or closure != {n for n, v in chosen.items() if v >= 0}:
            continue

        state, done = set(), set()
        def acyclic(name):
            if name in state:
                return False
            if name in done:
                return True
            state.add(name)
            if any(not acyclic(child) for child in edges.get(name, [])):
                return False
            state.remove(name)
            done.add(name)
            return True
        if not all(acyclic(name) for name in edges):
            continue

        key = tuple(vector)
        if best_key is None or key < best_key:
            best_key, best = key, {n: v for n, v in chosen.items() if v >= 0}

    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    n = len(jobs)

    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        selected = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = {j["id"] for j in selected}
        if ids & blocked or not mandatory <= ids:
            continue
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(selected, key=lambda j: (j["start"], j["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(j["value"] for j in selected)
        id_list = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and id_list > best_ids)):
            best_value, best_ids = value, id_list
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _component_08(data):
    import heapq

    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source, target = data["source"], data["target"]
    start_mask = bit.get(source, 0)
    start_state = (source, start_mask, 0)
    dist = {start_state: data["start"]}
    queue = [(data["start"], source, start_mask, 0)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if dist.get(state) != time:
            continue
        if node == target and mask == full and used == data["coupons"]:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


